head.script:
// 호출메뉴ID를 식별하기 위한 함수사용
// 세션정보를 얻기위한 함수사용
// 상장관련공통함수
scwin.fr_SecuGrpId = SECUGRP_ID_EW;
scwin.fr_MktId = $c.lc.fn_getMktId(); // 시장구분코드(유가, 코스닥) 전체), 기준은 로그인 사용자의 부서 소속을 기준으로 한다.

scwin.fn_GetPar, scwin.fn_SetPar;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.libRoundPanel.PanelToGroupBox(pan_Cnd);
        rdo_ISUR_CD.setValue("1");
        await scwin.getIsurcode();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05912.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Search_onclick = async function() {
    try {
        if (cmb_ISUR_CD.getSelectedIndex() === 0) {
            await $c.win.alert($c.stf.getMessageParam("MSG-0016", ""));
            cmb_ISUR_CD.focus();
            return;
        }
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05912.img_Search_onclick" });
    }
};

/**
 * @method
 * @name dts_OnLoadError
 * @description dts 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_OnLoadError = async function() {
    try {
        await $c.win.alert(dts);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05912.dts_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_OnLoadCompleted
 * @description dts 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_OnLoadCompleted = function(rowcount) {
    try {
        txb_TotCnt.setValue("총 " + rowcount + " 건");
        dts.setRowPosition(rowcount, 0);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05912.dts_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name img_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_Close_onclick = function() {
    try {
        window.close();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05912.img_Close_onclick" });
    }
};

/**
 * @method
 * @name img_Regist_onclick
 * @description 「신규」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Regist_onclick = async function() {
    try {
        if (cmb_ISUR_CD.getSelectedIndex() === 0) {
            await $c.win.alert($c.stf.getMessageParam("MSG-0016", ""));
            cmb_ISUR_CD.focus();
            return true;
        }
        if (cmb_RegistTyp.getSelectedIndex() === 0) {
            await $c.win.alert($c.stf.getMessageParam("MSG-0014", ""));
            cmb_RegistTyp.focus();
            return true;
        }
        scwin.fn_GetPar = scwin.getParNew;
        scwin.fn_SetPar = undefined;
        await scwin.newpreCreateFrame(cmb_RegistTyp.BindColVal, "");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05912.img_Regist_onclick" });
    }
};

/**
 * @method
 * @name img_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Excel_onclick = async function() {
    try {
        $c.stf.doLogSave("ULDSTF05912.xml", SCREN_PROCS_TP_CD_07);
        if (dts.getRowCount() > 0) {
            $c.data.downloadGridViewExcel(grd, {fileName: $c.lc.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + "매매거래정지내역", type: "8"});
        } else {
            await $c.win.alert(NO_EXCEL_DATA);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05912.img_Excel_onclick" });
    }
};

/**
 * @method
 * @name grd_OnDblClick
 * @description grd 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_OnDblClick = async function(row, colid) {
    try {
        scwin.fn_GetPar = scwin.getParUpdate; // 수정시 인수를 넘기는 function을 fn_GetPar란 변수에 할당, (팝업화면에서 참조하는 변수명이 fn_GetPar임)
        scwin.fn_SetPar = undefined;

        // 거래정지지정및해제구분코드 값 넘겨야함
        await scwin.newpreCreateFrame(dts.getCellData(dts.getRowPosition(), "HALT_DESNRELS_TP_CD"), dts.getCellData(dts.getRowPosition(), "TRD_HALT_STRT_DD"));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05912.grd_OnDblClick" });
    }
};

/**
 * @method
 * @name rdo_ISUR_CD_onselchange
 * @description rdo_ISUR_CD onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.rdo_ISUR_CD_onselchange = function() {
    try {
        if (rdo_ISUR_CD.getValue() === "1") {
            cmb_ISUR_CD.ComboDataID = "dts_ElwInst";
            cmb_ISUR_CD.setSelectedIndex(0);
        } else if (rdo_ISUR_CD.getValue() === "2") {
            cmb_ISUR_CD.ComboDataID = "dts_ElwUly";
            cmb_ISUR_CD.setSelectedIndex(0);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05912.rdo_ISUR_CD_onselchange" });
    }
};

/**
 * @method
 * @name cmb_ISUR_CD_onselchange
 * @description cmb_ISUR_CD onselchange 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cmb_ISUR_CD_onselchange = async function() {
    try {
        if (cmb_ISUR_CD.getSelectedIndex() !== 0) {
            await scwin.search();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05912.cmb_ISUR_CD_onselchange" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    url += "&SCREN_ID=" + "ULDSTF05912.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts",
        action : "/tradingSuspension.do",
        ref : "",
        target : "dts=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name getIsurcode
 * @description elw발행사
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getIsurcode = async function() {
    // elw발행사
    const sbmOptions = {
        id : "sbm_dts_ElwInst",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_ElwInst=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions2 = {
        id : "sbm_dts_ElwUly",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_ElwUly=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getParUpdate
 * @description 넘길 인수를 지정하는 펑션
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParUpdate = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = cmb_ISUR_CD.BindColVal; // 발행기관코드값
    arrPar[1] = cmb_ISUR_CD.getText(); // 발행기관명
    arrPar[2] = scwin.fr_SecuGrpId; // 증권그룹구분
    arrPar[3] = scwin.fr_MktId; // 시장구분
    arrPar[4] = dts.getCellData(dts.getRowPosition(), "bz_procs_no"); // 업무처리번호
    arrPar[5] = dts.getCellData(dts.getRowPosition(), "HALT_DESNRELS_TP_CD"); // 거래정지지정및해제구분코드
    arrPar[6] = rdo_ISUR_CD.getValue(); // 발행사/기초자산 구분값

    return arrPar.length;
};

/**
 * @method
 * @name getParNew
 * @description 신규생성시 지정하는 평션
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParNew = function(arrPar) {
    // 신규생성시 지정하는 평션
    arrPar[0] = cmb_ISUR_CD.BindColVal; // 발행기관코드값
    arrPar[1] = cmb_ISUR_CD.getText(); // 발행기관명
    arrPar[2] = scwin.fr_SecuGrpId; // 증권그룹구분
    arrPar[3] = scwin.fr_MktId; // 시장구분
    arrPar[4] = ""; // 신규작성시 업무처리번호는 없다.
    arrPar[5] = cmb_RegistTyp.BindColVal; // 거래정지지정및해제구분코드
    arrPar[6] = rdo_ISUR_CD.getValue(); // 발행사/기초자산 구분값

};

/**
 * @method
 * @name newpreCreateFrame
 * @description newpre Create Frame 처리
 * @param {*} arg arg
 * @param {String} startDd startDd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.newpreCreateFrame = async function(arg, startDd) {
    if (arg === "1" && startDd !== "") arg = "3";
    // alert(arg) ;
    /*
    0:지정, 1:해제, 2:지정및해제(유), 3:지정->해제
     */
    switch (arg) {
        case "0":
            const options = {
                id: "ULDSTF05913",
                title: $c.lc.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + " 매매거래정지 지정",
                type: "browserPopup",
                width: "700px",
                height: "545px",
                callbackFn: "scwin.popupCallback"
            };

            $c.win.openPopup("../lstproc/ULDSTF05913.gfm", options);
            break;
        case "2":
            const options2 = {
                id: "ULDSTF05915",
                title: $c.lc.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + " 매매거래정지 지정 및 해제",
                type: "browserPopup",
                width: "720px",
                height: "580px",
                callbackFn: "scwin.popupCallback"
            };

            $c.win.openPopup("../lstproc/ULDSTF05915.gfm", options2);
            break;
        case "3":
            const options3 = {
                id: "ULDSTF05932",
                title: $c.lc.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + " 매매거래정지 해제",
                type: "browserPopup",
                width: "685px",
                height: "690px",
                callbackFn: "scwin.popupCallback"
            };

            $c.win.openPopup("../lstproc/ULDSTF05932.gfm", options3);
            break;
    }

    // fn_search() ; // 다이얼로그 창이 닫히면 조회를 보낸다.
    cmb_RegistTyp.setSelectedIndex(0);
};
